                src = s_tl
            elif r < H // 2:
                src = s_tr
            elif c < W // 2:
                src = s_bl
            else:
                src = s_br

            # Calculate parity-based solid region
            # For TL: solid when min(r, c) % 2 == 0 and within range
            # For TR: solid when min(r, W-1-c) % 2 == 0 and within range

            # Determine solid condition based on row/col % 2
            is_solid = False
            if src == s_tl:
                # TL: fill when r%2==0 and c <= 2*r//2 + 1
                if r % 2 == 0:
                    if c <= r:
                        is_solid = True
            elif src == s_tr:
                # TR: fill when r%2==0 and (W-1-c) <= r
